#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    for (auto& lst : adj) sort(lst.begin(), lst.end());
    vector<char> seen(n + 1, 0);
    seen[1] = 1;
    vector<int> order = {1};
    for (size_t i = 0; i < order.size(); i++) {
        for (int w : adj[order[i]]) {
            if (!seen[w]) {
                seen[w] = 1;
                order.push_back(w);
            }
        }
    }
    for (size_t i = 0; i < order.size(); i++) cout << (i ? " " : "") << order[i];
    cout << "\n";

    return 0;
}

